@if($canRefund && auth()->user()->hasPermission('pos.advance-deposits.refund'))<div class="modal fade" id="advance-deposit-refund-modal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><form id="advance-deposit-refund-form" method="post" action="{{ route('pos.advance-deposits.refund',$advanceDeposit) }}">@csrf<div class="modal-header"><h2 class="h5 mb-0">ยกเลิกเอกสารรับเงินล่วงหน้า</h2><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="alert alert-warning">ยกเลิกได้เฉพาะใบรับเงินล่วงหน้าที่ยังไม่มีรายการตัดที่ใช้งานอยู่ และวันที่กลับรายการต้องอยู่ในงวดบัญชีที่เปิดอยู่ ระบบจะคืนเงินเข้าบัญชีเงินสด/ธนาคารเดิมทุกช่องทางตามยอดเดิม</div><div class="row g-3"><div class="col-md-4"><label class="form-label">วันที่กลับรายการ</label><input class="form-control" type="date" name="refund_date" value="{{ today()->format('Y-m-d') }}" required></div><div class="col-md-8"><label class="form-label">ช่องทางคืนเงิน</label><div class="border rounded-3 p-2">@foreach($advanceDeposit->tenders as $tender)<div class="d-flex justify-content-between gap-3"><span>{{ $tender->bankAccount?->code }} · {{ $tender->bankAccount?->name }}</span><strong>{{ number_format((float) $tender->amount, 2) }}</strong></div>@endforeach</div></div><div class="col-12"><label class="form-label">เหตุผล</label><textarea class="form-control" name="reason" rows="3" minlength="10" required></textarea></div></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">กลับ</button><button class="btn btn-danger js-advance-deposit-cancel" type="submit">ยกเลิกเอกสาร</button></div></form></div></div></div>@endif
