@push('scripts')<script>$(function(){const modal=$('#advance-deposit-refund-modal'),form=$('#advance-deposit-refund-form');$('#refund-advance-deposit').on('click',()=>bootstrap.Modal.getOrCreateInstance(modal[0]).show());form.on('submit',function(e){e.preventDefault();const button=form.find('[type="submit"]');if(button.data('submitting'))return;button.data('submitting',true).prop('disabled',true);$.post(form.attr('action'),form.serialize()).done(r=>Swal.fire({icon:'success',text:r.msg}).then(()=>location.reload())).fail(xhr=>Swal.fire({icon:'error',text:xhr.responseJSON?.message||'ไม่สามารถคืนเงินใบรับเงินล่วงหน้าได้'})).always(()=>button.data('submitting',false).prop('disabled',false));});});</script>@endpush
